INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('sm-150-snow-leopard', 'SM-150 Snow Leopard Armored Combat Snowmobile', 'rifts', 'vehicle', 'One driver.', 'One, on the back seat. Two big riders or two Light or Heavy Machines weighing no more than 700 pounds (315 kg) together cost nothing; 700-1,000 pounds (315-450 kg) costs 20% speed, -15% piloting and -1 dodge; anything heavier bogs it down (-70% speed, -40% piloting, -3 dodge, and the engine may burn out). Without a passenger the back seat carries strapped-down supplies.', '135 mph (216 km) top, usually cruising at 50-60 mph (80-96 km). The booster jets give up to 200 mph (320 km) for 45 seconds (3 melee rounds). -10% piloting, stunts and maneuvers above 100 mph (160 km). Leaps 12 feet (3.7 m) high and 25 feet (7.6 m) across, up to 30% more off a ramp; 40 feet (12.2 m) high and 90 feet (27.4 m) across with the boosters, with a piloting roll to land. Range unlimited.', 'None.', 'None.', 'Height 3 feet (0.9 m), width 4 feet (1.2 m) across the skis, length 7 feet 7 inches (2.3 m).', '564 pounds (254 kg)', 184, 1, NULL, 1700000, 'Black Market: 1.7-2.4 million credits, poor availability; the Sovietski Army keeps it to itself. Up to two light weapon systems can be added at extra cost, and up to 50 more M.D.C. at 5,000 credits per 10 M.D.C., from the Black Market and the Poles.', 'A long-serving Sovietski Army armored snowmobile: quick, low to the ground, well protected for its size, with a nose laser that swings 45 degrees in any direction and a smoke launcher at the back. Side-mounted booster jets give it a burst of speed for a getaway, a charge or a jump no ordinary sled could make. It runs down to -90 F (-67.7 C); colder than that the locks and ignition have a 01-70% chance to freeze and it is sluggish (-30% speed, -10% piloting). At -120 F (-84.4 C) or below the engine freezes within five minutes of shutting off and has a 01-50% chance every 15 minutes of stalling while running; a frozen engine will not start until it warms to 32 F (0 C). It handles well on snow and ice but stops badly on ice: -20% above 40 mph (64 km), -50% above 100 mph (160 km). Above 40 mph (64 km) on loose snow on a slope there is a 01-60% chance of starting an avalanche or slide. Cargo is whatever the riders carry, or about 400 pounds (180 kg) lashed on with no passenger. Nuclear, 10-year life. Sensors: Cyberlink, a Gromeko Battlefield Computer with friend-or-foe I.D., a medium-range radio (50 miles/80 km), an ejector seat and heated seats.', 'Rifts World Book 36: Sovietski p.182-184'),
  ('sm-212-red-lightning', 'SM-212 Red Lightning Fast-Attack Motorcycle', 'rifts', 'vehicle', 'One rider.', 'One rider pillion (human-sized or a Light Machine), and one more in a passenger sidecar.', '200 mph (320 km) top, half that off-road on rough ground, battlefields and broken roads; cruises at 60 mph (96 km). Leaps about 10 feet (3 m) high and 30 feet (9.1 m) across, or 30 feet (9.1 m) high and up to 100 feet (30.5 m) across with the jet boost and a piloting roll to land; with a sidecar halve both and land at -25%. Range effectively unlimited.', 'None.', 'None.', 'Height 4 feet (1.2 m), width 3 feet (0.9 m), length 8 feet (2.4 m).', '1,500 pounds (675 kg)', 160, 1, NULL, 1700000, 'Black Market: 1.7 million credits fully loaded with its nuclear supply, fair availability. Sidecars: 14,000 credits standard, 120,000 for a combat one fully loaded.', 'The Sovietski answer to the Warlords'' Tek-12 Bushbike (Warlords of Russia p.150): a heavy-framed attack bike built for humans, partial cyborgs and Light Machines, tough enough for paved roads, dirt tracks and open country. Small booster rockets under the frame let it hop obstacles, ravines, craters and broken road without losing speed. It carries a pair of lasers flanking the front wheel and a hidden mini-missile launcher, and takes a cargo, gunner or missile sidecar. Its nuclear supply keeps it running indefinitely, which makes it one of the bikes Reavers most want to steal. Any sidecar costs 20% speed, 30% jump distance, -10% piloting and -1 dodge. A sidecar passenger or the rider firing a handheld weapon cannot aim or make a Called Shot: it is Shooting Wild. Cargo: 100 pounds (45 kg) strapped on or in saddlebags; a cargo sidecar adds 500 pounds (225 kg) at -10% speed and -5% piloting, and no jumps. The cargo sidecar is a sealed box: up to 300 pounds (135 kg) with no further penalty, up to 500 pounds (225 kg) at -30% speed, half jumps, -20% piloting and -3 dodge. Nuclear, 15-year life. Sensors: Cyberlink, a Gromeko Battlefield Computer with friend-or-foe I.D. and a medium-range radio (50 miles/80 km), plus heated seats.', 'Rifts World Book 36: Sovietski p.184-185'),
  ('sm-349-street-sickle', 'SM-349 Street Sickle Heavy Attack Cyborg Trike', 'rifts', 'vehicle', 'One pilot, linked by Cyberlink, who must be bionic: a partial cyborg, a Cyber-Humanoid, or a Light Machine up to a moderately Heavy one.', 'One pillion rider (human-sized or a Light Machine), far more exposed than the pilot.', '200 mph (320 km) on paved or dirt roads; 60-85 mph (96-136 km) cruising and off-road. Range effectively unlimited.', 'None.', 'None.', 'Height 5 feet (1.5 m) to the top of the canopy, 7 feet (2.1 m) to the top of the gun turret; width 5 feet (1.5 m); length 12 feet (3.7 m).', '2.6 tons', 220, 1, NULL, 4000000, 'Black Market: 4-6 million credits fully loaded; much wanted, poor availability.', 'A three-wheeled cyborg attack trike, two broad M.D.C. wheels (each roughly 2 feet/0.6 m across the tread) in front and one behind, used by both the Sovietski Police and the Army; despite the name it works on any ground. The pilot lies forward between the front wheels under a black clamshell canopy that hides him almost completely and needs no screens, since a bionic pilot is wired straight into it. A heavy turret over the rear wheel mounts a rail gun firing armor piercing rounds (or an ion cannon) for Shocktroopers, Brodkil, Gargoyles, monsters and light to medium armor, backed by two front lasers and two rear mini-missile boxes. It serves as light armored cavalry: scouting, border patrol, fast response, escort, riot control, troop support, and riding with tank squads and Superheavy Machines, 1D4 trikes often joining a tank squad. Tankers out of their tanks favor it. The canopy must be destroyed before the pilot can be targeted, and even then he is a Called Shot at -5 (-2 for a passenger). Cargo: 300 pounds (135 kg) strapped on or on the passenger seat. Nuclear, 10-year life. Sensors: Cyberlink, a Gromeko Battlefield Computer with friend-or-foe I.D. and a medium-range radio (50 miles/80 km), plus a heated seat and pilot compartment.', 'Rifts World Book 36: Sovietski p.185-187');

