INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('sm-150-snow-leopard', 1, 'Laser Nose Gun', '2D6 M.D. single blast, 5D6 M.D. triple pulse', 1, '2,000 feet (610 m)', 'Each single shot or short burst uses one melee attack.', 'Effectively unlimited.', NULL, 'Adjustable pulse laser in the nose with a 45-degree arc up, down and to either side, so the rider can aim up at Brodkil, Gargoyles, cyborg Shocktroopers and low flyers. Assault, then defense.'),
  ('sm-150-snow-leopard', 2, 'Smoke Launcher', 'None. One canister makes a thick smoke cloud of 20 foot (6.1 m) radius lasting 1D6+4 minutes, half that in a strong wind.', 0, 'Dropped behind the snowmobile as it pulls away.', 'One at a time or volleys of 2 or 4; volleys add up to a bigger cloud.', '8.', NULL, 'On one rear side. Covers the rider''s escape, especially with the boosters lit, or gives other troops time to move.'),
  ('sm-212-red-lightning', 1, 'Fixed Forward Wheel Lasers (2)', '2D6 M.D. single blast from one, 4D6 M.D. from both', 1, '2,000 feet (610 m)', 'Each single or double blast uses one melee attack.', 'Effectively unlimited.', NULL, 'Pulse lasers on either side of the front wheel, powered by the bike''s nuclear supply and able to fire linked; mostly for bigger vehicles and cyborgs. Assault, then defense.'),
  ('sm-212-red-lightning', 2, 'Mini-Missile Launcher', 'Varies with the missile; usually armor piercing or fragmentation', 1, 'Varies with the missile, typically one mile (1.6 km)', 'One at a time or volleys of 2, 3, 4 or all 8.', '8.', NULL, 'Hidden behind two sliding panels in the front cowling; fires straight ahead and takes any mini-missile. Anti-cyborg, then anti-armor.'),
  ('sm-212-red-lightning', 3, 'Sidecar Option A: Mini-Missile Sidecar', 'Varies with the missile; typically armor piercing (1D4x10 M.D. to a 3 foot/0.9 m radius) or fragmentation (5D6 M.D. to a 20 foot/6.1 m radius)', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 3, 4 or 6.', '24.', NULL, 'Optional sidecar holding a second load of mini-missiles, its launcher wired into the bike. Sidecar penalties as in the description.'),
  ('sm-212-red-lightning', 4, 'Sidecar Option B: Passenger Combat (Gunner) Sidecar', 'Rail gun: 4D6 M.D. per 20-round burst or 1D4 M.D. per round; riot control rounds can be loaded. Laser: 2D6 M.D. per blast.', 1, 'Rail gun 4,000 feet (1,219 m); laser 2,000 feet (610 m)', 'Each burst or single shot uses one melee attack.', 'Rail gun: 500-round drum in the sidecar, 25 bursts. Laser: 20 shots per standard E-Clip, with 10 clips carried.', NULL, 'Optional sidecar for one soldier or Light Machine and a crew-worked light rail gun or laser (pick one), mounted ahead of the gunner with a 90-degree arc to the side away from the rider and 45 degrees up and down. Assault and anti-personnel, then defense.'),
  ('sm-349-street-sickle', 1, 'Heavy Rail Gun or Ion Cannon (rear turret)', 'Rail gun: 1D4x10 M.D. per 20-round burst (riot control rounds 1D4 S.D.C. per burst). Ion cannon: 1D4x10 M.D. per blast.', 1, 'Rail gun 4,000 feet (1,219 m); ion cannon 3,000 feet (914 m)', 'Each rail gun burst or ion blast uses one melee attack.', 'Rail gun: 1,000-round belt-fed drum, 50 bursts. Ion cannon: unlimited.', NULL, 'Big turret on top over the back wheel, built as one or the other; the art shows the rail gun. Anti-cyborg and anti-monster, then anti-armor.'),
  ('sm-349-street-sickle', 2, 'Mini-Missile Launchers (2)', 'Standard load: 5 armor piercing (1D4x10 M.D.), 5 plasma (1D6x10 M.D.) and 2 smoke; any mini-missile can be used. Riot load: 8 tear gas (as short-range missiles), 2 smoke and 2 high explosive for breaching.', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2, 4 or 6.', '12: six per launcher, plus one full reload of 12 carried aboard, loaded by hand at one minute per missile.', NULL, 'A lidded box launcher on each side of the big gun. Anti-personnel, then assault. Missile types: Rifts Ultimate Edition p.363.'),
  ('sm-349-street-sickle', 3, 'Light Lasers (2)', '2D6 M.D. per blast, 4D6 M.D. dual blast at one target', 1, '2,000 feet (610 m)', 'Each single or dual blast uses one melee attack.', 'Effectively unlimited.', NULL, 'One above each front wheel, turning 360 degrees but mostly aimed ahead and to the sides; used when ammunition runs low and to shoot down incoming missiles. Assault and anti-personnel, then defense.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('sm-150-snow-leopard', 'sm-212-red-lightning', 'sm-349-street-sickle');
SELECT 'their 23 locations are in' AS assertion, count(*) AS got, 23 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('sm-150-snow-leopard', 'sm-212-red-lightning', 'sm-349-street-sickle');
SELECT 'their 9 weapon entries are in' AS assertion, count(*) AS got, 9 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('sm-150-snow-leopard', 'sm-212-red-lightning', 'sm-349-street-sickle');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('sm-150-snow-leopard', 'sm-212-red-lightning', 'sm-349-street-sickle') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

